import { useCallback, useMemo } from 'react'
import { DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import { Container, CustomText } from '../../../../../components'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { MANUAL_ORDER } from '../../../../../constants/pkgCode'
import { clearLocalStorage } from '../../../../../helpers/localstorage'
import { NEW_SUCCESS_PROOF_IMG } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { OfflineSuccessStyle } from './index.style'

function OfflineSuccess ({ match, history }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const pageConfig = useMemo(() => {
    const isManualOrder = urlParams.purchaseType === MANUAL_ORDER
    const title = `${LANG_STRINGS.confirmation} ${LANG_STRINGS.order}`
    return {
      title,
      isManualOrder
    }
  }, [urlParams])

  const handleToOrderDetail = useCallback(() => {
    // clear the localstorage so tha
    // we will call the order detail api from the review page container
    clearLocalStorage()
    history.push({
      pathname: `/offline/detail/${urlParams.quoteId}`
    })
  }, [history, urlParams.quoteId])

  const handleBackToHome = useCallback(() => {
    history.push({
      pathname: '/dashboard'
    })
  }, [history])

  return (
    <Container
      title={pageConfig.title}
      hideBottomTabs
      hideBackButton
      backBtnId='offlineSuccessBack'
      className='bg-white'
    >
      <OfflineSuccessStyle>
        <DisplayFlexCCC className='offline-success-img-container'>
          <img src={NEW_SUCCESS_PROOF_IMG} alt='Success' />
          <CustomText
            color={AgentColorPallette.black}
            size='15px'
            bottom='4px'
            top='10px'
            weight={800}
            textAlign='center'
          >
            {LANG_STRINGS.orderSent}
          </CustomText>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size='13px'
            bottom='10px'
            textAlign='center'
          >
            {LANG_STRINGS.thankYouToTrustInOurService}
          </CustomText>
        </DisplayFlexCCC>
        <div className='bottom-btn-box'>
          <ButtonWithIcon
            text={LANG_STRINGS.viewYourOrder}
            onClick={handleToOrderDetail}
            className='border-btm btn-radius'
            isArrowButton
          />
          <ButtonWithIcon
            text={LANG_STRINGS.backToHomeSentence}
            onClick={handleBackToHome}
            className='btn-radius'
            isArrowButton
          />
        </div>
      </OfflineSuccessStyle>
    </Container>
  )
}

export default OfflineSuccess
